import React from 'react';
import { motion } from 'framer-motion';
import { HiOutlineArrowSmRight } from 'react-icons/hi';

/**
 * A futuristic, glassmorphic stats card component with neural network animations
 */
const StatsCard = ({ 
  title, 
  value, 
  change, 
  icon: Icon, 
  color = 'neural', 
  onClick,
  showMoreLink = false
}) => {
  // Enhanced color mapping for different card types
  const cardColors = {
    blue: {
      bg: 'from-blue-500/30 to-blue-600/20',
      border: 'border-blue-400/30',
      glow: 'rgba(59, 130, 246, 0.3)',
      icon: 'text-blue-400',
      accent: '#3B82F6'
    },
    green: {
      bg: 'from-green-500/30 to-green-600/20',
      border: 'border-green-400/30',
      glow: 'rgba(74, 222, 128, 0.3)',
      icon: 'text-green-400',
      accent: '#4ADE80'
    },
    purple: {
      bg: 'from-purple-500/30 to-purple-600/20',
      border: 'border-purple-400/30',
      glow: 'rgba(168, 85, 247, 0.3)',
      icon: 'text-purple-400',
      accent: '#A855F7'
    },
    cyan: {
      bg: 'from-cyan-500/30 to-cyan-600/20',
      border: 'border-cyan-400/30',
      glow: 'rgba(34, 211, 238, 0.3)',
      icon: 'text-cyan-400',
      accent: '#22D3EE'
    },
    neural: {
      bg: 'from-neural-400/30 to-neural-600/20',
      border: 'border-neural-400/30',
      glow: 'rgba(100, 200, 255, 0.3)',
      icon: 'text-neural-400',
      accent: '#64C8FF'
    }
  };

  const colorSet = cardColors[color] || cardColors.neural;
  const isPositiveChange = change > 0;
  
  // Neural network nodes
  const nodes = React.useMemo(() => {
    const nodeCount = 5;
    const nodeArray = [];
    
    for (let i = 0; i < nodeCount; i++) {
      nodeArray.push({
        x: 10 + Math.random() * 80,
        y: 10 + Math.random() * 80,
        size: 2 + Math.random() * 2,
        delay: Math.random() * 2
      });
    }
    
    return nodeArray;
  }, []);
  
  // Neural connections
  const connections = React.useMemo(() => {
    const connectionArray = [];
    
    // Create 3 connections between random nodes
    for (let i = 0; i < 3; i++) {
      const sourceIndex = Math.floor(Math.random() * nodes.length);
      let targetIndex;
      do {
        targetIndex = Math.floor(Math.random() * nodes.length);
      } while (targetIndex === sourceIndex);
      
      connectionArray.push({
        startX: nodes[sourceIndex].x,
        startY: nodes[sourceIndex].y,
        endX: nodes[targetIndex].x,
        endY: nodes[targetIndex].y,
        active: i === 0 // Make one connection active/highlighted
      });
    }
    
    return connectionArray;
  }, [nodes]);

  // Advanced card animation variants
  const cardVariants = {
    initial: { 
      opacity: 0,
      y: 20,
      scale: 0.95
    },
    animate: { 
      opacity: 1,
      y: 0,
      scale: 1,
      transition: {
        type: "spring",
        stiffness: 300,
        damping: 25,
        delay: 0.1
      }
    },
    hover: {
      scale: 1.03,
      boxShadow: "0 10px 20px rgba(0,0,0,0.19), 0 6px 6px rgba(0,0,0,0.23)",
      transition: {
        type: "spring",
        stiffness: 400,
        damping: 15
      }
    },
    tap: {
      scale: 0.98,
      boxShadow: "0 5px 10px rgba(0,0,0,0.15), 0 3px 3px rgba(0,0,0,0.1)",
      transition: {
        type: "spring",
        stiffness: 500,
        damping: 15
      }
    }
  };

  // Neural node animation
  const NeuralNode = ({ color, size = 3, x, y, delay = 0 }) => (
    <motion.div 
      className="absolute rounded-full"
      style={{
        backgroundColor: color,
        width: `${size}px`,
        height: `${size}px`,
        left: `${x}%`,
        top: `${y}%`,
        filter: 'blur(1px)'
      }}
      initial={{ opacity: 0 }}
      animate={{ 
        opacity: [0.2, 0.7, 0.2]
      }}
      transition={{
        duration: 2 + Math.random() * 2,
        repeat: Infinity,
        delay: delay
      }}
    />
  );

  // Neural connection line
  const NeuralConnection = ({ startX, startY, endX, endY, color, active = false }) => {
    // Calculate control points for curve
    const midX = (startX + endX) / 2;
    const midY = (startY + endY) / 2;
    const variance = (Math.random() - 0.5) * 20;
    
    const ctrlX = midX + variance;
    const ctrlY = midY + variance;
    
    // Path data for quadratic curve
    const pathData = `M ${startX} ${startY} Q ${ctrlX} ${ctrlY}, ${endX} ${endY}`;
    
    return (
      <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
        <path 
          d={pathData}
          stroke={color}
          strokeOpacity={active ? 0.4 : 0.15}
          strokeWidth={active ? 1 : 0.8}
          fill="none"
          strokeDasharray={active ? "none" : "3,3"}
          style={{
            filter: active ? `drop-shadow(0 0 2px ${color})` : 'none'
          }}
        />
        
        {active && (
          <motion.circle 
            r="2"
            fill={color}
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: [0, 0.8, 0],
              pathOffset: [0, 1]
            }}
            transition={{ 
              duration: 2, 
              repeat: Infinity,
              ease: "linear",
              repeatDelay: 1
            }}
            style={{
              offsetPath: `path("${pathData}")`,
              offsetRotate: "0deg"
            }}
          />
        )}
      </svg>
    );
  };

  return (
    <motion.div
      className={`stats-card bg-gray-900/40 backdrop-blur-xl rounded-xl border ${colorSet.border} p-4 relative overflow-hidden`}
      variants={cardVariants}
      initial="initial"
      animate="animate"
      whileHover="hover"
      whileTap="tap"
      onClick={onClick}
      style={{
        boxShadow: `0 4px 15px ${colorSet.glow}`,
      }}
    >
      {/* Glassmorphic background effect */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        {/* Base background */}
        <div className={`absolute inset-0 bg-gradient-to-br ${colorSet.bg} opacity-30`} />
        
        {/* Grid background */}
        <div 
          className="absolute inset-0 opacity-20"
          style={{ 
            backgroundImage: `linear-gradient(${colorSet.accent}10 1px, transparent 1px), linear-gradient(90deg, ${colorSet.accent}10 1px, transparent 1px)`,
            backgroundSize: '10px 10px'
          }}
        />
        
        {/* Top highlight */}
        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent" />
        
        {/* Neural nodes */}
        {nodes.map((node, i) => (
          <NeuralNode 
            key={`node-${i}`}
            color={colorSet.accent}
            size={node.size}
            x={node.x}
            y={node.y}
            delay={node.delay}
          />
        ))}
        
        {/* Neural connections */}
        {connections.map((conn, i) => (
          <NeuralConnection 
            key={`conn-${i}`}
            startX={`${conn.startX}%`}
            startY={`${conn.startY}%`}
            endX={`${conn.endX}%`}
            endY={`${conn.endY}%`}
            color={colorSet.accent}
            active={conn.active}
          />
        ))}
        
        {/* Scan line effect */}
        <motion.div 
          className="absolute h-0.5 w-full"
          style={{ 
            backgroundColor: `${colorSet.accent}20`,
            boxShadow: `0 0 5px ${colorSet.accent}50`,
            top: '0%'
          }}
          animate={{ 
            opacity: [0, 0.3, 0], 
            top: ['0%', '100%', '0%']
          }}
          transition={{ 
            duration: 6, 
            repeat: Infinity, 
            ease: "linear",
            repeatDelay: 3
          }}
        />
      </div>
      
      {/* Icon */}
      <div className="flex justify-between mb-3 relative z-10">
        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${colorSet.icon} relative`}>
          <div className={`absolute inset-0 rounded-lg bg-gradient-to-br ${colorSet.bg} opacity-50`} />
          <div className="relative z-10">
            {Icon}
          </div>
          
          {/* Pulsing glow */}
          <motion.div 
            className="absolute inset-0 rounded-lg"
            style={{ backgroundColor: `${colorSet.accent}20` }}
            animate={{ opacity: [0.3, 0.6, 0.3] }}
            transition={{ duration: 2, repeat: Infinity }}
          />
        </div>
        
        {/* Change indicator */}
        <div 
          className={`flex items-center text-sm font-medium ${
            isPositiveChange ? 'text-green-400' : change < 0 ? 'text-red-400' : 'text-gray-400'
          }`}
        >
          <span>{isPositiveChange ? '+' : ''}{change}%</span>
          <motion.div 
            className="w-4 h-4 flex items-center justify-center ml-1"
            initial={{ rotate: isPositiveChange ? -45 : 45 }}
            animate={{ rotate: isPositiveChange ? 0 : 90 }}
          >
            <HiOutlineArrowSmRight />
          </motion.div>
        </div>
      </div>
      
      {/* Content */}
      <div className="relative z-10">
        <h3 className="text-sm text-gray-400 font-medium mb-1">{title}</h3>
        <div className="flex justify-between items-end">
          <div className="text-2xl font-bold text-white">{value}</div>
          
          {showMoreLink && (
            <motion.div 
              className="text-sm text-neural-400 flex items-center cursor-pointer"
              whileHover={{ x: 2 }}
            >
              More <HiOutlineArrowSmRight className="ml-1" />
            </motion.div>
          )}
        </div>
      </div>
    </motion.div>
  );
};

export default StatsCard; 